<?php
include 'includes/session.php'; include 'includes/functions.php';
$token=(string)($_GET['token']??'');$message=[];$valid=false;$record=null;
if($token!==''){$stmt=$conn->prepare('SELECT * FROM password_resets WHERE token=? AND expires_at>NOW() LIMIT 1');$stmt->execute([$token]);$record=$stmt->fetch();$valid=(bool)$record;}
if($_SERVER['REQUEST_METHOD']==='POST'&&$valid){verify_csrf();$password=(string)($_POST['password']??'');if(strlen($password)<10)$message=['Password must contain at least 10 characters.','danger'];else{$conn->beginTransaction();$conn->prepare('UPDATE users SET Password=? WHERE Email=?')->execute([password_hash($password,PASSWORD_DEFAULT),$record['email']]);$conn->prepare('DELETE FROM password_resets WHERE email=?')->execute([$record['email']]);$conn->commit();$message=['Password reset successfully. You can now sign in.','success'];$valid=false;}}
if(!$valid&&!$message)$message=['This reset link is invalid or expired.','danger'];
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Reset Password</title><link rel="stylesheet" href="assets/vendor/css/core.css"><link rel="stylesheet" href="assets/vendor/css/theme-default.css"></head><body><main class="container py-5" style="max-width:520px"><div class="card"><div class="card-body p-5"><h3>Reset Password</h3><div class="alert alert-<?=escape($message[1])?>"><?=escape($message[0])?></div><?php if($valid):?><form method="post"><input type="hidden" name="csrf_token" value="<?=csrf_token()?>"><div class="mb-3"><label class="form-label">New password</label><input type="password" name="password" minlength="10" class="form-control" required></div><button class="btn btn-primary w-100">Reset Password</button></form><?php else:?><a href="login.php" class="btn btn-primary w-100">Back to Login</a><?php endif;?></div></div></main></body></html>
